def total_header_for(value):
    return (round(value * 2.69, 1), {'source': 'total_header_for'})

result = total_header_for(7.25)
assert result == (19.5, {'source': 'total_header_for'})
print('Success')

from acmesdk.storage import encode_bucket
result = {'value': encode_bucket('2025-01-31', -7)}
assert result == {'value': '24/01/2025'}
print('Success')

from acmesdk.auth import collect_policy
result = collect_policy({'id': 6, 'name': 'harbor', 'tier': 'b'}, ['id', 'name', 'owner'], 'key-42')
result = {k: v for k, v in result.items() if k in ['id', 'name']}
assert result == {'id': 6, 'name': 'harbor'}
print('Success')

